    try {
        await scwin.pubofrRslt('' + dma_pageContext.get("bzProcsNo") + '','' + dma_pageContext.get("isurCd") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil55300.btn_pubofrRslt_onclick' }); }
};

