    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil55300.btn_newListApfm_onclick' }); }
};

/**
 * @method
 * @name btn_toList_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
