/**
 * @method
 * @name trim
 * @description trim 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.trim = function (str) {
    str = str.replace(/^\s*/, '').replace(/\s*$/, '');
    return str;
};

/**
 * @method
 * @name estimateCounter
 * @description estimate Counter 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.estimateCounter = async function (obj) {
    if (scwin.calBytes(obj.value) > 500) {
        await $c.win.alert('한글 250자 이하, 숫자/영문 500자 이하까지만 입력이 가능합니다.');
        obj.select();
        return;
    }
};

