    return;
};

/**
 * @method
 * @name getStringSize
 * @description get String Size 처리
 * @param {*} message message
 * @returns {void}
 * @hidden N
 */
scwin.getStringSize = function (message) {
    let i, len = 0;
    for (i = 0; i < message.length; i++) {
        (message.charCodeAt(i) > 255) ? len += 2 : len++;
    }
    return len;
};

