    obj.focus();
};

/**
 * @method
 * @name execActiveSpac
 * @description exec Active Spac 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.execActiveSpac = function (val) {
    const st = $c.util.getComponent("cal_exstStrtDd");
    const ed = $c.util.getComponent("cal_exstEndDd");
    const rmk = $c.util.getComponent("txa_exstDeadlineRemk");
    if (val === "N") {
        st.setDisabled(true);
        ed.setDisabled(true);
        rmk.setDisabled(true);
        st.setStyle('background-color', "#f0f0f0");
        ed.setStyle('background-color', "#f0f0f0");
        rmk.setStyle('background-color', "#f0f0f0");
    } else {
        st.setDisabled(false);
        ed.setDisabled(false);
        rmk.setDisabled(false);
        st.setStyle('background-color', "#ffffff");
        ed.setStyle('background-color', "#ffffff");
        rmk.setStyle('background-color', "#ffffff");
    }
};

